.ds-demo { box-sizing: border-box; background: var(--bg, #100e15); color: var(--ink, #f5f1fb); font: 15px/1.7 Anuphan, sans-serif; }
.ds-demo :where(button, input, a, header, nav, article, section, div, label, details, summary, span) { box-sizing: border-box; }
.ds-demo :where(button, input) { font: inherit; }
.ds-demo button { cursor: pointer; color: inherit; border: 1px solid var(--line, #38303f); background: transparent; }
.ds-demo button:disabled { cursor: not-allowed; opacity: .6; }
.ds-demo button:hover:not(:disabled) { border-color: var(--purple, #bb98ff); }
.ds-demo :where(button,a,input,summary):focus-visible { outline: 3px solid var(--purple, #bb98ff); outline-offset: 4px; }
.ds-demo a { color: inherit; text-underline-offset: 5px; }
.ds-demo :where(button,a,input,summary) { touch-action: manipulation; -webkit-tap-highlight-color: transparent; }
.ds-demo input { color: var(--ink, #f5f1fb); min-width: 0; caret-color: var(--purple, #bb98ff); }
.ds-demo input::placeholder { color: var(--muted, #b8adca); opacity: 1; }
.ds-demo :where(h2,h3,p) { margin: 0; }
.ds-demo :where(h2,h3) { text-wrap: balance; font-weight: 500; }
.ds-demo h2 { line-height: 1.4; letter-spacing: -.02em; }
.ds-demo p { overflow-wrap: anywhere; }
.ds-demo svg { flex-shrink: 0; stroke-width: 1.7; vertical-align: middle; }
.ds-demo .ds-account-form { max-width: 440px;
  display: grid;
  gap: 13px; }
.ds-demo .ds-account-form input { padding: 13px;
  border: 1px solid var(--line, #38303f);
  border-radius: 12px;
  background: var(--surface, #1b1722); }
.ds-demo .ds-account-form p { color: var(--muted, #b8adca);
  font-size: 12px; }
.ds-demo .ds-account-form button:not(.ds-primary) { border-radius: 12px; padding: 12px; }

